import{_ as a,o,c as n,a2 as s}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Introducción y arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"cloud/kubernetes/01-introduccion-y-arquitectura.md","filePath":"cloud/kubernetes/01-introduccion-y-arquitectura.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"cloud/kubernetes/01-introduccion-y-arquitectura.md"};function r(i,e,c,l,d,u){return o(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="introduccion-y-arquitectura" tabindex="-1">Introducción y arquitectura <a class="header-anchor" href="#introduccion-y-arquitectura" aria-label="Permalink to &quot;Introducción y arquitectura&quot;">​</a></h1><p>Kubernetes (K8s) orquesta contenedores en un <strong>cluster</strong>: describes el estado deseado (Pods, réplicas, red, secretos) y el plano de control se encarga de acercar la realidad a esa descripción. No sustituye a Docker como runtime: asume que ya tienes <strong>imágenes</strong> y necesita un runtime de contenedores en cada nodo (containerd es lo habitual).</p><p>No es Docker Compose a escala. Compose arranca contenedores en una máquina (o un swarm). Kubernetes programa cargas en <strong>varios nodos</strong>, reconcilia de forma continua y habla un API propio (<code>apiVersion</code> / <code>kind</code>), no un fichero <code>services:</code> de Compose.</p><p>Documentación oficial: <a href="https://kubernetes.io/docs/concepts/overview/" target="_blank" rel="noreferrer">Overview</a>, <a href="https://kubernetes.io/docs/concepts/overview/components/" target="_blank" rel="noreferrer">Componentes</a>.</p><h2 id="que-problema-resuelve" tabindex="-1">Qué problema resuelve <a class="header-anchor" href="#que-problema-resuelve" aria-label="Permalink to &quot;Qué problema resuelve&quot;">​</a></h2><p>Cuando una aplicación en contenedores tiene que:</p><ul><li>sobrevivir a la caída de un proceso o de una máquina,</li><li>escalar réplicas,</li><li>exponerse con DNS interno y, si aplica, un balanceador,</li><li>montar configuración y secretos sin rehacer la imagen,</li></ul><p>hace falta un orquestador. Kubernetes cubre eso con objetos declarativos. No compila tu código, no es un PaaS cerrado y no te obliga a una base de datos concreta: si cabe en un contenedor, puede correr en el cluster.</p><h2 id="cluster-plano-de-control-y-nodos" tabindex="-1">Cluster: plano de control y nodos <a class="header-anchor" href="#cluster-plano-de-control-y-nodos" aria-label="Permalink to &quot;Cluster: plano de control y nodos&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl / CI  --&gt;  API Server  --&gt;  etcd</span></span>
<span class="line"><span>                      |    \\</span></span>
<span class="line"><span>                      |     scheduler (elige nodo)</span></span>
<span class="line"><span>                      |     controllers (réplicas, endpoints, …)</span></span>
<span class="line"><span>                      v</span></span>
<span class="line"><span>                 kubelet en cada nodo --&gt; runtime --&gt; Pods</span></span></code></pre></div><ul><li><strong>API Server:</strong> única puerta de entrada. <code>kubectl apply</code> es un PUT/PATCH a este API.</li><li><strong>etcd:</strong> estado del cluster. Si se pierde sin backup, se pierde el cluster.</li><li><strong>Scheduler:</strong> asigna Pods pendientes a nodos con recursos y restricciones.</li><li><strong>Controller manager:</strong> bucles de reconciliación (Deployment, ReplicaSet, Job, …).</li><li><strong>Kubelet:</strong> agente en el nodo; ejecuta lo que el API le asigna y reporta estado.</li><li><strong>Kube-proxy / CNI:</strong> red de Pods y Services (la implementación concreta depende del cluster).</li></ul><p>El capítulo <a href="./09-arquitectura-interna-del-cluster">Arquitectura interna del cluster</a> profundiza en estos componentes. Aquí basta el mapa para no confundir “el YAML” con “el nodo”.</p><h2 id="objetos-que-vas-a-usar-pronto" tabindex="-1">Objetos que vas a usar pronto <a class="header-anchor" href="#objetos-que-vas-a-usar-pronto" aria-label="Permalink to &quot;Objetos que vas a usar pronto&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Objeto</th><th>Rol</th></tr></thead><tbody><tr><td>Pod</td><td>Unidad que se ejecuta (uno o varios contenedores que comparten red y volúmenes).</td></tr><tr><td>Deployment</td><td>Plantilla de Pod + número de réplicas y rolling update.</td></tr><tr><td>Service</td><td>IP/DNS estable delante de Pods que nacen y mueren.</td></tr><tr><td>Namespace</td><td>Partición lógica (equipos, entornos).</td></tr></tbody></table><p>No crees Pods sueltos para una app: usa un Deployment. El siguiente capítulo enseña los manifiestos.</p><p>Comandos para mirar el cluster (con <code>kubectl</code> configurado):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster-info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span></code></pre></div><p>Si <code>get nodes</code> falla, el problema es el kubeconfig o el API Server, no el YAML de la aplicación.</p><h2 id="compose-frente-a-kubernetes" tabindex="-1">Compose frente a Kubernetes <a class="header-anchor" href="#compose-frente-a-kubernetes" aria-label="Permalink to &quot;Compose frente a Kubernetes&quot;">​</a></h2><p>Un <code>docker-compose.yml</code> con <code>services</code> e <code>image: nginx</code> <strong>no</strong> es un manifiesto de Kubernetes. En K8s esperarías <code>apiVersion</code>, <code>kind: Deployment</code> (o <code>Pod</code>) y <code>spec.containers</code>. Mezclar ambos es un error habitual cuando se copia una plantilla.</p><table tabindex="0"><thead><tr><th>Compose</th><th>Kubernetes</th></tr></thead><tbody><tr><td>Un fichero, un host (típico)</td><td>API + muchos nodos</td></tr><tr><td><code>docker compose up</code></td><td><code>kubectl apply</code> (reconciliación continua)</td></tr><tr><td>Reinicio local</td><td>ReplicaSet / Deployment recrean Pods</td></tr><tr><td>Redes <code>bridge</code> del motor</td><td>CNI + Service/Ingress</td></tr></tbody></table><p>Compose sigue siendo útil en desarrollo; el <a href="./../docker-compose/01-introduccion-y-casos-de-uso">manual de Docker Compose</a> cubre ese caso. Cuando necesitas scheduling, self-healing y un API declarativo entre máquinas, pasas a Kubernetes.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Pegar YAML de Compose en un cluster y esperar que <code>kubectl apply</code> lo acepte.</li><li>Tratar el Pod como si fuera “el contenedor de Docker” y olvidar que el Deployment es quien lo mantiene vivo.</li><li>Editar a mano Pods creados por un controller: el ReplicaSet los sustituye.</li><li>Exponer cargas con <code>NodePort</code> o <code>hostNetwork</code> sin entender la red del cluster.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Trabaja siempre contra el API (<code>kubectl</code>, GitOps), no “entrando al nodo a lanzar contenedores”.</li><li>Versiona imágenes (<code>nginx:1.27</code>, no <code>latest</code>) cuando llegues a manifiestos.</li><li>Separa entornos por namespace o por cluster; no mezcles producción con pruebas en el mismo namespace por costumbre.</li><li>Aprende a leer <code>kubectl describe</code> y eventos antes de añadir operadores.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Con un cluster de prueba (kind, k3d, minikube o un managed), ejecuta <code>kubectl get nodes</code> y <code>kubectl get pods -A</code>.</li><li>Identifica qué procesos son plano de control y cuáles son add-ons (CoreDNS, CNI).</li><li>Abre el siguiente capítulo y compara un Pod con un Deployment: quién es el dueño (<code>ownerReferences</code>).</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-pods-deployments-y-replicasets">Pods, Deployments y ReplicaSets</a>.</p>`,30)])])}const b=a(t,[["render",r]]);export{h as __pageData,b as default};
